27: func StopGracefully(ctx context.Context, inst *limatype.Instance, isRestart bool) error {
28: 	if inst.Status != limatype.StatusRunning {
29: 		if isRestart {
30: 			logrus.Warn("The instance is not running, continuing with the restart")
31: 			return nil
32: 		}
33: 		return fmt.Errorf("expected status %q, got %q (maybe use `limactl stop -f`?)", limatype.StatusRunning, inst.Status)
34: 	}
35: 
36: 	begin := time.Now() // used for logrus propagation
37: 	if requested, err := autostart.RequestStop(ctx, inst); err != nil && !errors.Is(err, autostart.ErrNotSupported) {
38: 		return fmt.Errorf("failed to request stop via autostart manager: %w", err)
39: 	} else if !requested {
40: 		logrus.Infof("Sending SIGINT to hostagent process %d", inst.HostAgentPID)
41: 		if err := osutil.SysKill(inst.HostAgentPID, osutil.SigInt); err != nil {
42: 			logrus.Error(err)
43: 		}
44: 	}
45: 
46: 	logrus.Info("Waiting for the host agent and the driver processes to shut down")
47: 	err := waitForHostAgentTermination(ctx, inst, begin)
48: 	if err != nil {
49: 		return err
50: 	}
51: 
52: 	logrus.Info("Waiting for the instance to shut down")
53: 	return waitForInstanceShutdown(ctx, inst)
54: }
