56: func waitForHostAgentTermination(ctx context.Context, inst *limatype.Instance, begin time.Time) error {
57: 	ctx, cancel := context.WithTimeout(ctx, 3*time.Minute+10*time.Second)
58: 	defer cancel()
59: 
60: 	var receivedExitingEvent bool
61: 	onEvent := func(ev hostagentevents.Event) bool {
62: 		if len(ev.Status.Errors) > 0 {
63: 			logrus.Errorf("%+v", ev.Status.Errors)
64: 		}
65: 		if ev.Status.Exiting {
66: 			receivedExitingEvent = true
67: 			return true
68: 		}
69: 		return false
70: 	}
71: 
72: 	haStdoutPath := filepath.Join(inst.Dir, filenames.HostAgentStdoutLog)
73: 	haStderrPath := filepath.Join(inst.Dir, filenames.HostAgentStderrLog)
74: 
75: 	if err := hostagentevents.Watch(ctx, haStdoutPath, haStderrPath, begin, true, onEvent); err != nil {
76: 		return err
77: 	}
78: 
79: 	if !receivedExitingEvent {
80: 		return errors.New("did not receive an event with the \"exiting\" status")
81: 	}
82: 
83: 	return nil
84: }
