491: func (l *LimaVzDriver) Stop(ctx context.Context) error {
492: 	logrus.Info("Shutting down VZ")
493: 	canStop := l.machine.CanRequestStop()
494: 
495: 	if canStop {
496: 		_, err := l.machine.RequestStop()
497: 		if err != nil {
498: 			return err
499: 		}
500: 
501: 		if *l.Instance.Config.OS == limatype.DARWIN {
502: 			// macOS VM does not respond to l.machine.RequestStop(),
503: 			// so we need to run `shutdown -h now` in the VM via SSH for graceful shutdown.
504: 			if err := l.requestStopViaSSH(ctx); err != nil {
505: 				logrus.WithError(err).Warn("Failed to request shutdown via SSH")
506: 			}
507: 		}
508: 
509: 		// Most Linux machines shutdown within 5 seconds, but macOS machines can take longer.
510: 		timeout := time.After(30 * time.Second)
511: 		ticker := time.NewTicker(500 * time.Millisecond)
512: 		for {
513: 			select {
514: 			case <-timeout:
515: 				return errors.New("vz timeout while waiting for stop status")
516: 			case <-ticker.C:
517: 				l.machine.mu.Lock()
518: 				stopped := l.machine.stopped
519: 				l.machine.mu.Unlock()
520: 				if stopped {
521: 					return nil
522: 				}
523: 			}
524: 		}
525: 	}
526: 
527: 	return errors.New("vz: CanRequestStop is not supported")
528: }
